/* ═══════════════════════════════════════════════════════════════
   X.v1 Developer Portal — Stylesheet (Dark IDE Theme)
   ═══════════════════════════════════════════════════════════════ */

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;800&family=Fira+Code:wght@400;500;600&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600&family=Outfit:wght@300;400;500;600;700&family=Tajawal:wght@400;500;700;800&display=swap');

:root {
  --bg-app: #0d0d10;
  --bg-sidebar: #121216;
  --bg-card: #17171d;
  --bg-card-hover: #1e1e26;
  --bg-input: #15151b;

  --border-subtle: rgba(255, 255, 255, 0.07);
  --border-focus: rgba(251, 191, 36, 0.4);

  --accent-dev: #f59e0b;
  --accent-dev-glow: rgba(245, 158, 11, 0.35);
  --accent-cyan: #06b6d4;
  --accent-emerald: #10b981;
  --accent-rose: #f43f5e;

  --text-main: #f3f4f6;
  --text-muted: #9ca3af;
  --text-dim: #6b7280;
  --hl-important: #f59e0b;
  --hl-critical: #ef4444;
  --hl-success: #10b981;
  --hl-info: #38bdf8;
  --hl-keyword: #a78bfa;

  --font-sans: 'Outfit', 'Tajawal', sans-serif;
  --font-mono: 'Fira Code', monospace;
  --chat-font-size: 15px;
}

/* 🎨 Theme 2: Emerald Matrix */
[data-theme="emerald"] {
  --bg-app: #06110d !important;
  --bg-sidebar: #091913 !important;
  --bg-card: #0e241c !important;
  --bg-card-hover: #132e24 !important;
  --bg-input: #0a1b15 !important;
  --accent-dev: #10b981 !important;
  --accent-dev-glow: rgba(16, 185, 129, 0.4) !important;
  --border-subtle: rgba(16, 185, 129, 0.16) !important;
}

/* 🎨 Theme 3: Velvet Amethyst */
[data-theme="amethyst"] {
  --bg-app: #0f0a1c !important;
  --bg-sidebar: #150e27 !important;
  --bg-card: #1e1338 !important;
  --bg-card-hover: #261947 !important;
  --bg-input: #170f2c !important;
  --accent-dev: #a855f7 !important;
  --accent-dev-glow: rgba(168, 85, 247, 0.4) !important;
  --border-subtle: rgba(168, 85, 247, 0.16) !important;
}

/* 🎨 Theme 4: Oceanic Sapphire */
[data-theme="sapphire"] {
  --bg-app: #060e1a !important;
  --bg-sidebar: #0a1526 !important;
  --bg-card: #0f2038 !important;
  --bg-card-hover: #152c4d !important;
  --bg-input: #0c1a2e !important;
  --accent-dev: #0ea5e9 !important;
  --accent-dev-glow: rgba(14, 165, 233, 0.4) !important;
  --border-subtle: rgba(14, 165, 233, 0.16) !important;
}

/* 🔤 Font Family Options */
[data-font="cairo"] {
  --font-sans: 'Cairo', 'Outfit', sans-serif !important;
}
[data-font="tajawal"] {
  --font-sans: 'Tajawal', 'Outfit', sans-serif !important;
}
[data-font="mono"] {
  --font-sans: 'Fira Code', 'JetBrains Mono', monospace !important;
}
[data-font="inter"] {
  --font-sans: 'Inter', 'Outfit', sans-serif !important;
}

/* 📏 Font Size Options */
[data-size="sm"] {
  --chat-font-size: 13.5px !important;
}
[data-size="md"] {
  --chat-font-size: 15px !important;
}
[data-size="lg"] {
  --chat-font-size: 16.5px !important;
}
[data-size="xl"] {
  --chat-font-size: 18px !important;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}

*::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

*::-webkit-scrollbar-track {
  background: transparent;
}

*::-webkit-scrollbar-thumb {
  background: transparent;
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: padding-box;
}

*:hover,
*.is-scrolling {
  scrollbar-color: rgba(156, 163, 175, 0.42) transparent;
}

*:hover::-webkit-scrollbar-thumb,
*.is-scrolling::-webkit-scrollbar-thumb {
  background: rgba(156, 163, 175, 0.42);
  background-clip: padding-box;
}

*:hover::-webkit-scrollbar-thumb:hover,
*.is-scrolling::-webkit-scrollbar-thumb:hover {
  background: rgba(209, 213, 219, 0.62);
  background-clip: padding-box;
}

html, body {
  height: 100%;
  height: var(--app-height, 100vh);
  min-height: var(--app-height, 100vh);
  max-height: var(--app-height, 100vh);
  width: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  overscroll-behavior-y: none;
  background: var(--bg-app);
  color: var(--text-main);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -webkit-text-size-adjust: 100%;
  user-select: text;
  direction: ltr;
  text-align: left;
}

#app {
  display: flex;
  flex-direction: row;
  height: 100%;
  height: var(--app-height, 100vh);
  max-height: var(--app-height, 100vh);
  width: 100vw;
  overflow: hidden;
  position: relative;
}

/* ─── Backdrop Overlay ─── */
#overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  z-index: 110;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
}

#overlay.active {
  opacity: 1;
  pointer-events: auto;
}

/* ─── Sidebar ─── */
#sidebar {
  width: 300px;
  background: var(--bg-sidebar);
  border-right: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 120;
}

.sidebar-header {
  padding: 16px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-subtle);
}

.dev-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 16px;
  letter-spacing: 0.02em;
  color: #fff;
}

.dev-badge {
  background: rgba(245, 158, 11, 0.15);
  color: var(--accent-dev);
  border: 1px solid rgba(245, 158, 11, 0.3);
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}

.sidebar-nav {
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  direction: ltr;
  text-align: left;
}

.dev-btn-primary {
  width: 100%;
  padding: 10px 16px;
  background: linear-gradient(135deg, #f59e0b, #d97706);
  color: #000;
  border: none;
  border-radius: 10px;
  font-weight: 700;
  font-size: 13.5px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.2s ease;
  box-shadow: 0 4px 14px var(--accent-dev-glow);
}

.dev-btn-primary:hover {
  transform: translateY(-1px);
  filter: brightness(1.1);
}

.sidebar-section-title {
  padding: 10px 18px 4px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--text-dim);
  letter-spacing: 0.05em;
}

#conversations-list {
  flex: 1;
  overflow-y: auto;
  padding: 6px 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.conv-item {
  padding: 10px 12px;
  border-radius: 8px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--text-muted);
  font-size: 13px;
  transition: all 0.15s ease;
}

.conv-item:hover {
  background: var(--bg-card);
  color: var(--text-main);
  justify-content: flex-start;
  direction: ltr;
  text-align: left;
}

.conv-item.active {
  background: rgba(245, 158, 11, 0.12);
  color: #fff;
  border: 1px solid rgba(245, 158, 11, 0.3);
  font-weight: 600;
}

.conv-item-del {
  opacity: 0;
  background: transparent;
  border: none;
  color: var(--text-dim);
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 4px;
  transition: all 0.15s ease;
}

.conv-item:hover .conv-item-del {
  opacity: 1;
}

.conv-item-del:hover {
  color: var(--accent-rose);
  background: rgba(244, 63, 94, 0.15);
}

.sidebar-footer {
  padding: 12px 16px;
  border-top: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: #0f0f13;
}

.sidebar-link-btn {
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--border-subtle);
  background: transparent;
  color: var(--text-muted);
  font-size: 12.5px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  transition: all 0.15s ease;
}

.sidebar-link-btn:hover {
  background: var(--bg-card);
  color: var(--text-main);
  border-color: rgba(255, 255, 255, 0.15);
}

/* ─── Main Content Area ─── */
#main {
  flex: 1;
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  position: relative;
  overflow: hidden;
  background: var(--bg-app);
}

/* ─── Header Toolbar ─── */
#header {
  height: 52px;
  padding: 0 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-subtle);
  background: #111115;
  z-index: 20;
  gap: 8px;
  direction: ltr;
  text-align: left;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
  direction: ltr;
}

.icon-btn {
  background: transparent;
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  padding: 6px 10px;
  height: 34px;
  border-radius: 8px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 12.5px;
  font-weight: 500;
  transition: all 0.15s ease;
  white-space: nowrap;
  flex-shrink: 0;
}

.icon-btn:hover {
  color: #fff;
  background: var(--bg-card);
  border-color: rgba(255, 255, 255, 0.2);
}

.repo-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 9px;
  background: rgba(16, 185, 129, 0.1);
  border: 1px solid rgba(16, 185, 129, 0.25);
  color: #34d399;
  border-radius: 999px;
  font-size: 11.5px;
  font-family: var(--font-mono);
  white-space: nowrap;
  flex-shrink: 0;
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #10b981;
  box-shadow: 0 0 6px #10b981;
  flex-shrink: 0;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
  direction: ltr;
}

/* Header Responsiveness on Tablets & Mobile */
@media (max-width: 820px) {
  .header-btn-label {
    display: none;
  }
  .icon-btn {
    padding: 6px 8px;
    font-size: 14px;
  }
}

@media (max-width: 480px) {
  #header {
    padding: 0 10px;
  }
  .repo-badge-text {
    font-size: 11px;
  }
  .header-right {
    gap: 4px;
  }
  .icon-btn {
    padding: 6px;
  }
}

/* ─── Centered Welcome Screen & Greeting Hero ─── */
.dev-welcome-hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  margin: auto auto;
  padding: 30px 16px;
  gap: 16px;
  max-width: 680px;
  width: 100%;
  animation: fadeIn 0.3s ease;
}

.dev-welcome-star {
  width: 64px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 38px;
  background: rgba(245, 158, 11, 0.1);
  border: 1px solid rgba(245, 158, 11, 0.3);
  border-radius: 20px;
  color: var(--accent-dev);
  box-shadow: 0 0 25px rgba(245, 158, 11, 0.15);
  margin-bottom: 4px;
}

.dev-welcome-title {
  font-size: 26px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.01em;
}

.dev-welcome-sub {
  font-size: 14.5px;
  color: var(--text-muted);
  line-height: 1.6;
  max-width: 520px;
}

.dev-welcome-chips {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-top: 12px;
  max-width: 580px;
}

.welcome-chip {
  padding: 9px 16px;
  background: #181820;
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  color: #e5e7eb;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease;
  font-family: var(--font-sans);
}

.welcome-chip:hover {
  background: rgba(245, 158, 11, 0.15);
  color: #fbbf24;
  border-color: rgba(245, 158, 11, 0.4);
  transform: translateY(-1px);
}

/* ─── Centered Completion & System Banners ─── */
.dev-centered-banner {
  margin: 16px auto;
  max-width: 600px;
  width: 100%;
  text-align: center;
  background: #14141a;
  border: 1px solid rgba(16, 185, 129, 0.35);
  border-radius: 16px;
  padding: 18px 20px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  animation: fadeIn 0.25s ease;
}

/* ─── Chat Area ─── */
#chat-area {
  flex: 1 1 0%;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior-y: contain;
  scroll-behavior: smooth;
  touch-action: pan-y;
  padding: 16px 16px 8px;
  display: flex;
  flex-direction: column;
}

.chat-container {
  width: 100%;
  max-width: 768px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ─── Message Rows ─── */
.message-row {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
}

/* AI Message Model Attribution Tag (تحت الرد بلون خفيف وأنيق) */
.msg-model-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 500;
  color: #71717a;
  background: transparent;
  border: none;
  padding: 1px 4px;
  width: fit-content;
  margin-top: 2px;
  margin-bottom: 0;
  font-family: var(--font-sans);
  opacity: 0.8;
  transition: opacity 0.15s ease, color 0.15s ease;
  user-select: none;
  direction: ltr;
  text-align: left;
}

.msg-model-tag:hover {
  opacity: 1;
  color: #9ca3af;
}

.msg-model-tag .model-tag-name {
  color: #71717a;
  font-weight: 500;
}

.message-row.user {
  width: 100%;
  align-self: flex-end !important;
  align-items: flex-end;
  margin-left: auto !important;
  margin-right: 0 !important;
  direction: ltr !important;
}

.message-row.user .msg-content {
  background: transparent;
  border: none;
  color: #fff;
  padding: 2px 0;
  border-radius: 0;
  max-width: 80%;
  width: fit-content;
  font-size: 14.5px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}

.message-row.ai {
  align-self: flex-start;
  align-items: stretch;
  width: 100%;
}

.message-row.ai .msg-content {
  color: var(--text-main);
  font-size: 14.5px;
  line-height: 1.65;
  word-break: break-word;
}

.message-row.is-rtl,
.message-row.user.is-rtl,
.message-row.ai.is-rtl {
  direction: rtl;
  text-align: right;
}

.message-row.is-ltr,
.message-row.user.is-ltr,
.message-row.ai.is-ltr {
  direction: ltr;
  text-align: left;
}

.message-row.user.is-rtl .msg-content {
  direction: rtl;
  text-align: right;
}

.message-row.user.is-ltr .msg-content {
  direction: ltr;
  text-align: left;
}

.message-copy-bar {
  width: 80%;
  display: flex;
  justify-content: flex-start;
  margin-top: 3px;
  direction: ltr;
}
.user-copy-outside {
  width: 24px;
  height: 22px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-subtle);
  border-radius: 7px;
  background: transparent;
  color: var(--text-dim);
  cursor: pointer;
  opacity: 0.72;
}
.user-copy-outside:hover {
  color: var(--text-main);
  border-color: rgba(255, 255, 255, 0.2);
  opacity: 1;
}

.message-row.ai.is-rtl .msg-content {
  direction: rtl;
  text-align: right;
  unicode-bidi: plaintext;
}

.message-row.ai.is-ltr .msg-content {
  direction: ltr;
  text-align: left;
  unicode-bidi: plaintext;
}

.message-line {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  width: 100%;
}
.message-speaker {
  flex: 0 0 24px;
  width: 24px;
  height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-subtle);
  border-radius: 7px;
  background: rgba(255,255,255,.04);
  font-size: 13px;
  line-height: 1;
  user-select: none;
}
.user-speaker { color: #93c5fd; }
.ai-speaker { color: #c4b5fd; }
.message-row.user .message-line {
  width: 100%;
  justify-content: flex-end;
}
.message-row.user .message-line .msg-content {
  max-width: none;
}

/* ─── Code Blocks & Diff Previews (Always LTR) ─── */
pre, code {
  direction: ltr !important;
  text-align: left !important;
  unicode-bidi: isolate !important;
}
pre {
  background: #0a0a0d !important;
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  padding: 14px;
  overflow-x: auto;
  margin: 10px 0;
  font-family: var(--font-mono) !important;
  font-size: 13px !important;
  color: #e5e7eb;
}

code {
  font-family: var(--font-mono);
  font-size: 0.9em;
  background: rgba(255, 255, 255, 0.08);
  padding: 2px 6px;
  border-radius: 4px;
  color: #fbbf24;
}

pre code {
  background: transparent !important;
  padding: 0 !important;
  color: inherit !important;
}

/* ─── Interactive Dev Proposal Box ─── */
.dev-proposal-box {
  margin-top: 14px;
  background: #121217;
  border: 1px solid rgba(245, 158, 11, 0.4);
  border-radius: 14px;
  padding: 12px;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 7px;
  animation: fadeIn 0.25s ease;
  direction: ltr;
  text-align: left;
}

.dev-proposal-box.blocked {
  border-color: rgba(239, 68, 68, 0.6);
  background: rgba(239, 68, 68, 0.04);
}
.circuit-breaker-banner {
  padding: 8px 12px;
  border-radius: 8px;
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.35);
  color: #fca5a5;
  font-size: 12px;
  line-height: 1.45;
  font-weight: 500;
}

.dev-proposal-title {
  font-size: 14px;
  font-weight: 700;
  color: #fbbf24;
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: flex-start;
  direction: ltr;
  text-align: left;
}

.dev-proposal-desc {
  font-size: 13px;
  color: var(--text-muted);
  direction: ltr;
  text-align: left;
}

.dev-proposal-btns {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
  justify-content: flex-start;
  direction: ltr;
}

.dev-btn-action {
  padding: 5px 10px;
  border-radius: 6px;
  font-size: 11.5px;
  font-weight: 500;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-main);
  transition: all 0.15s ease;
  line-height: 1.2;
}

.dev-btn-action.preview {
  background: rgba(59, 130, 246, 0.12);
  border-color: rgba(59, 130, 246, 0.3);
  color: #93c5fd;
}
.dev-btn-action.preview:hover {
  background: rgba(59, 130, 246, 0.22);
  border-color: rgba(59, 130, 246, 0.5);
  color: #bfdbfe;
}

.dev-btn-action.deploy {
  background: rgba(16, 185, 129, 0.12);
  border-color: rgba(16, 185, 129, 0.3);
  color: #6ee7b7;
}
.dev-btn-action.deploy:hover {
  background: rgba(16, 185, 129, 0.22);
  border-color: rgba(16, 185, 129, 0.5);
  color: #a7f3d0;
}

.dev-btn-action.copy {
  background: rgba(168, 85, 247, 0.12);
  border-color: rgba(168, 85, 247, 0.3);
  color: #d8b4fe;
}
.dev-btn-action.copy:hover {
  background: rgba(168, 85, 247, 0.22);
  border-color: rgba(168, 85, 247, 0.5);
  color: #f3e8ff;
}

.dev-btn-action.review-fix {
  background: rgba(255, 255, 255, 0.04);
  border-color: rgba(255, 255, 255, 0.12);
  color: var(--text-muted);
}
.dev-btn-action.review-fix:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.22);
  color: var(--text-main);
}

.dev-btn-action.cancel {
  background: rgba(244, 63, 94, 0.08);
  border-color: rgba(244, 63, 94, 0.25);
  color: #fca5a5;
  padding: 5px 8px;
}
.dev-btn-action.cancel:hover {
  background: rgba(244, 63, 94, 0.18);
  border-color: rgba(244, 63, 94, 0.45);
}

/* ─── Collapsible Mini Patch Drawer inside Proposal Card ─── */
.dev-patch-drawer {
  margin-top: 10px;
  background: #09090c;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  overflow: hidden;
  animation: fadeIn 0.2s ease;
  transition: all 0.25s ease;
}

.dev-patch-drawer.hidden {
  display: none;
}

.patch-drawer-header {
  padding: 8px 12px;
  background: rgba(255, 255, 255, 0.04);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--text-muted);
}

.btn-copy-patch {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  color: #fbbf24;
  padding: 3px 8px;
  font-size: 11px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-copy-patch:hover {
  background: rgba(245, 158, 11, 0.2);
  color: #fff;
}

.patch-drawer-code {
  max-height: 220px;
  overflow-y: auto;
  padding: 12px;
  margin: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  background: transparent !important;
  font-family: var(--font-mono) !important;
  font-size: 12px !important;
  line-height: 1.55;
  color: #a5f3fc !important;
  direction: ltr !important;
  text-align: left !important;
}

/* ─── Modern Circular Pull To Refresh Indicator ─── */
.pull-refresh-indicator {
  position: fixed;
  top: 14px;
  left: 50%;
  transform: translate(-50%, -80px) scale(0.85);
  width: 42px;
  height: 42px;
  background: rgba(30, 30, 34, 0.96);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-dev);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.7);
  z-index: 9999;
  opacity: 0;
  pointer-events: none;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.2s ease;
}

.pull-refresh-indicator.pull-bottom {
  top: auto;
  bottom: 85px;
  transform: translate(-50%, 80px) scale(0.85);
}

.pull-refresh-indicator.visible {
  opacity: 1;
}

.pull-refresh-indicator.refreshing {
  opacity: 1;
  transform: translate(-50%, 20px) scale(1);
}

.pull-refresh-indicator.pull-bottom.refreshing {
  opacity: 1;
  transform: translate(-50%, -18px) scale(1);
}

.pull-refresh-spinner {
  width: 21px;
  height: 21px;
  color: var(--accent-dev);
  transition: transform 0.08s linear;
}

.pull-refresh-indicator.refreshing .pull-refresh-spinner {
  animation: modernSpin 0.7s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

@keyframes modernSpin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* ─── Bottom Refresh Confirmation Modal ─── */
.bottom-refresh-modal {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.68);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
}

.bottom-refresh-modal.show {
  opacity: 1;
  pointer-events: auto;
}

.bottom-refresh-card {
  background: #18181c;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 18px;
  padding: 22px 24px;
  max-width: 340px;
  width: 100%;
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.85);
  text-align: center;
  direction: ltr;
  transform: scale(0.92);
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.bottom-refresh-modal.show .bottom-refresh-card {
  transform: scale(1);
}

.bottom-refresh-header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: #fff;
  font-weight: 700;
  font-size: 16px;
}

.bottom-refresh-desc {
  font-size: 13.5px;
  color: var(--text-muted);
  margin: 10px 0 18px;
  line-height: 1.5;
}

.bottom-refresh-actions {
  display: flex;
  gap: 10px;
  justify-content: center;
}

.btn-refresh-confirm {
  flex: 1;
  padding: 10px 16px;
  background: linear-gradient(135deg, #f59e0b, #d97706);
  color: #fff;
  border: none;
  border-radius: 10px;
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  transition: transform 0.15s ease, opacity 0.15s ease;
}

.btn-refresh-confirm:hover {
  opacity: 0.95;
  transform: translateY(-1px);
}

.btn-refresh-cancel {
  flex: 1;
  padding: 10px 16px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-muted);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.btn-refresh-cancel:hover {
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
}

/* ─── Ultra-Modern Developer Terminal / Code Card ─── */
.dev-terminal-card {
  margin: 14px 0;
  background: #15151a;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6), 0 0 15px rgba(0, 0, 0, 0.35);
  direction: ltr !important;
  text-align: left !important;
  font-family: var(--font-sans);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.dev-terminal-card:hover {
  border-color: rgba(245, 158, 11, 0.35);
  box-shadow: 0 14px 38px rgba(0, 0, 0, 0.7), 0 0 20px rgba(245, 158, 11, 0.12);
}

.terminal-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 14px;
  background: #1d1d24;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  gap: 10px;
}

.terminal-header-left {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  overflow: hidden;
}

.terminal-icon-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 7px;
  background: rgba(245, 158, 11, 0.15);
  border: 1px solid rgba(245, 158, 11, 0.35);
  color: #fbbf24;
  border-radius: 6px;
  font-size: 11.5px;
  font-weight: 700;
  font-family: var(--font-mono);
  line-height: 1.2;
  flex-shrink: 0;
}

.terminal-lang-title {
  font-size: 13px;
  font-weight: 700;
  color: #f3f4f6;
  white-space: nowrap;
  flex-shrink: 0;
}

.terminal-cmd-preview {
  font-size: 11.5px;
  color: #9ca3af;
  font-family: var(--font-mono);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  opacity: 0.85;
}

.terminal-header-right {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.terminal-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 10px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #e5e7eb;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
  font-family: var(--font-sans);
}

.terminal-action-btn:hover {
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
  border-color: rgba(255, 255, 255, 0.25);
}

.terminal-action-btn.copy-btn:hover {
  background: rgba(245, 158, 11, 0.18);
  border-color: rgba(245, 158, 11, 0.4);
  color: #fbbf24;
}

.terminal-card-body {
  padding: 12px 14px;
  background: #0d0d10;
  overflow-x: auto;
  transition: max-height 0.25s ease;
}

.terminal-card-body.collapsed {
  max-height: 125px;
  overflow-y: hidden;
  position: relative;
}

.terminal-card-body.collapsed::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 48px;
  background: linear-gradient(to bottom, transparent, #0d0d10);
  pointer-events: none;
}

.terminal-card-body pre {
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  overflow: visible !important;
}

.terminal-card-body pre code {
  display: block;
  font-family: var(--font-mono) !important;
  font-size: 13px !important;
  line-height: 1.6 !important;
  color: #e5e7eb !important;
  background: transparent !important;
  padding: 0 !important;
  white-space: pre !important;
  tab-size: 2;
}

.terminal-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 14px;
  background: #191920;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
}

.terminal-footer-status {
  display: flex;
  align-items: center;
  gap: 6px;
  direction: ltr;
  text-align: left;
}

.terminal-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2.5px 8px;
  background: rgba(16, 185, 129, 0.14);
  border: 1px solid rgba(16, 185, 129, 0.35);
  color: #34d399;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 700;
  font-family: var(--font-mono);
}

.terminal-footer-meta {
  font-size: 11.5px;
  color: var(--text-dim);
  font-family: var(--font-mono);
}

/* ─── Floating Input Bar (Identical to User Chatbox) ─── */
#input-section {
  padding: 6px 14px 18px;
  padding-bottom: max(18px, env(safe-area-inset-bottom, 18px));
  background: transparent;
  flex-shrink: 0;
  z-index: 25;
  width: 100%;
  display: flex;
  justify-content: center;
}

.input-container {
  max-width: 768px;
  width: 100%;
  margin: 0 auto;
  background: #17171d;
  border: 1px solid var(--border-subtle);
  border-radius: 26px;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
  transition: border-color 0.25s ease, box-shadow 0.25s ease;
  position: relative;
  overflow: visible;
}

.input-container:focus-within {
  border-color: rgba(245, 158, 11, 0.45);
  box-shadow: 0 8px 32px rgba(245, 158, 11, 0.12), 0 0 0 1px rgba(245, 158, 11, 0.25);
}

/* Thinking glow removed per request */
.input-container.thinking{border-color:var(--border-subtle) !important;box-shadow:0 8px 32px rgba(0,0,0,0.5) !important;animation:none !important}
.input-container.thinking::before{display:none !important}

.typing-bubble {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 2px 0 !important;
  backdrop-filter: none !important;
}

/* Thinking flow — no background, icon left + sentence, smooth upward dots (same as chat) */
.thinking-flow {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 8px;
  padding-left: 2px;
}
.thinking-flow {
  border-left: 1px solid var(--border-subtle);
  padding-left: 14px;
}
.thinking-flow-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12.5px;
  color: var(--text-dim);
  opacity: 0;
  transform: translateY(6px);
  animation: thinkingFlowIn 0.35s ease forwards;
  position: relative;
}
.thinking-flow-item .flow-dot{
  position:absolute;
  left:-16px;
  top:7px;
  width:7px;
  height:7px;
  border-radius:50%;
  background:var(--accent-dev);
  box-shadow:0 0 6px var(--accent-dev-glow);
  display:none;
}
.thinking-flow-item.reached .flow-dot{display:block;animation:flowDotPulse 1.1s ease-in-out infinite}
/* Highlight by importance — dev also */
.hl-important { color: var(--hl-important); font-weight: 700; }
.hl-critical { color: var(--hl-critical); font-weight: 700; }
.hl-success { color: var(--hl-success); font-weight: 700; }
.hl-info { color: var(--hl-info); font-weight: 600; }
.hl-keyword { color: var(--hl-keyword); font-weight: 600; background: rgba(167,139,250,0.12); padding: 1px 4px; border-radius: 4px; }

.thinking-flow-item .flow-icon {
  font-size: 13px;
  flex-shrink: 0;
  width: 16px;
  text-align: center;
}
.thinking-flow-item .flow-text {
  flex: 1;
  line-height: 1.4;
}
.thinking-flow-item .flow-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--accent-dev);
  opacity: 0;
  flex-shrink: 0;
}
.thinking-flow-item.reached .flow-dot{
  opacity:0.9;
  animation: flowDotPulse 1.2s ease-in-out infinite;
}
@keyframes flowDotPulse{
  0%{transform:scale(0.8);opacity:0.5}
  50%{transform:scale(1.3);opacity:1}
  100%{transform:scale(0.8);opacity:0.5}
}
@keyframes thinkingFlowIn {
  to { opacity: 1; transform: translateY(0); }
}
@keyframes flowDotUp {
  0% { transform: translateY(0); opacity: 0.3; }
  50% { transform: translateY(-5px); opacity: 1; }
  100% { transform: translateY(-10px); opacity: 0; }
}

